import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';

const Sidebar = () => {
  const { sidebarOpen, setSidebarOpen } = useApp();
  const navigate = useNavigate();

  const close = () => setSidebarOpen(false);

  const handleUpload = () => {
    close();
    navigate('/upload');
  };

  return (
    <>
      <div
        className={`sidebar-overlay ${sidebarOpen ? 'active' : ''}`}
        onClick={close}
      />
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="sidebar-logo">
          <img className="brand-logo-img sidebar-brand-img" src="/assets/ecoistic-logo.png" alt="Ecoistic logo" />
          <div className="sidebar-logo-text">
            <span>ECOISTIC</span>
            <span>GROW GREEN TOGETHER</span>
          </div>
        </div>

        <nav className="sidebar-nav">
          <NavLink to="/" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">Home</span>
            Home
          </NavLink>
          <NavLink to="/history" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">Log</span>
            Success History
          </NavLink>
          <NavLink to="/about" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">Info</span>
            About Us
          </NavLink>
          <button onClick={handleUpload}>
            <span className="nav-icon">Add</span>
            Upload
          </button>
          <NavLink to="/settings" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">Set</span>
            Settings
          </NavLink>
        </nav>

        <div className="sidebar-planter">
          <img className="planter-img" src="/assets/sidebar-planter.png" alt="Person planting a sapling" />
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
